const activityCatalog=[
{name:'A little of everything',icon:'✧',detail:'Your buddy wanders, reads, dances, and takes little breaks.'},
{name:'Walking around',icon:'👣',detail:'Exploring the room, one little paw at a time.'},
{name:'Reading',icon:'📖',detail:'Turning the pages of a favorite story.'},
{name:'Drinking water',icon:'💧',detail:'Lifting a glass for a refreshing sip.'},
{name:'Dancing',icon:'♫',detail:'Little steps, big ears, and a whole lot of joy.'},
{name:'Sleeping',icon:'☾',detail:'Curled up on the sofa for a cozy nap.'},
{name:'Eating together',icon:'🍽',detail:'Sharing the meal you chose.'}
];
const routine=['Walking around','Reading','Walking around','Drinking water','Dancing','Sleeping'];
const contextDirector=window.DiaContext.createDirector();
let currentVisual={action:'Idle',context:null,simulated:false};
function currentActivity(now=Date.now()){
 const base=activity==='A little of everything'?routine[Math.floor((now-activityStarted)/13000)%routine.length]:activity==='Eating together'&&!state.sharedMeal?'Reading':activity;
 currentVisual=contextDirector.select({connection:dexcom,thresholds:state.thresholds,now,baseAction:base,manual:activity!=='A little of everything',busy:!!document.querySelector('.bunny-intro[open]')||modal.open||now<celebrationUntil||now<tryOnUntil,hidden:document.hidden||!!$('#content')?.hidden,reducedMotion:!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,enabled:state.contextualEmotes!==false});
 return currentVisual.action;
}
function activityButtons(){return activityCatalog.filter(a=>!['A little of everything','Eating together'].includes(a.name)).map(a=>`<button data-act="${a.name}" title="${a.detail}" aria-label="${a.name}">${a.icon}<span>${a.name}</span></button>`).join('')}
function setActivity(name){if(!activityCatalog.some(a=>a.name===name))return;if(name==='Eating together'&&!state.sharedMeal){toast('Name your meal below, then share it with '+buddyName()+'.');return}activity=name;activityStarted=Date.now();if(page==='home'){drawRoom();document.querySelectorAll('[data-act]').forEach(b=>b.classList.toggle('selected',b.dataset.act===name))}}
function updateActionCaption(a){const meta=activityCatalog.find(x=>x.name===a)||{icon:'✧',detail:'A quiet moment, at your own pace.'};const title=$('#action-title'),detail=$('#action-detail'),icon=$('#action-icon');if(title)title.textContent=currentVisual.context?buddyName()+' · '+currentVisual.label:a==='Eating together'?'Eating with '+buddyName():buddyName()+' is '+a.toLowerCase();if($('#room')?._misoPose?.travel&&a!=='Walking around'&&title)title.textContent=buddyName()+' is walking over';if(detail)detail.textContent=currentVisual.context?'A contextual illustration, not a treatment instruction.':a==='Eating together'?'Sharing '+state.sharedMeal.name+'. Taking little bites, just like you.':meta.detail;if(icon)icon.textContent=currentVisual.context?'✧':meta.icon;const note=$('#context-visual-note');if(note){note.dataset.context=currentVisual.context||'none';note.textContent=(currentVisual.simulated?'Dexcom sandbox · Simulated readings. ':'')+(currentVisual.dataState==='stale'?'The last reading is stale; showing a neutral routine. ':currentVisual.dataState!=='recent'?'Current glucose data is unavailable; showing a neutral routine. ':'')+'Last update: '+(Number.isFinite(Date.parse(dexcom.reading?.timestamp))?new Date(dexcom.reading.timestamp).toLocaleString():'No reading received')+'. Contextual visuals are fictional, not symptoms or treatment instructions. Follow your own care plan.';}}
function openActivities(){showModal(`<div class="eyebrow">${escapeHTML(buddyName())}’S EVERYDAY MOMENTS</div><h2>A whole little life.</h2><p>Pick an activity, or let ${escapeHTML(buddyName())} follow a little routine.</p><div class="activity-picker">${activityCatalog.map(a=>`<button class="${activity===a.name?'selected':''}" data-act="${a.name}"><b>${a.icon}</b><span>${a.name==='Eating together'?'Eating with '+escapeHTML(buddyName()):a.name}<small>${a.detail}</small></span></button>`).join('')}</div>`)}
function bindWorldInteractions(){const canvas=$('#room');canvas.onclick=e=>{const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*480/rect.width,y=(e.clientY-rect.top)*310/rect.height;if(x<115&&y>155)setActivity('Walking around');else if(x>350&&y>180)setActivity(state.sharedMeal?'Eating together':'Drinking water');else if(x>325&&y<175)setActivity('Reading');else if(x>150&&x<350&&y>170)setActivity('Sleeping');else setActivity('Walking around')};}
function mealCard(){return `<section class="card meal-card"><div class="meal-heading"><span class="meal-spark" aria-hidden="true">✦</span><div><div class="eyebrow">A LITTLE MEAL, TOGETHER</div><h2>What’s on your plate?</h2><p>Describe your dish, toppings, and sides. ${escapeHTML(buddyName())} will share a pixel-art version.</p></div><span class="ai-tag">LOCAL MEAL STUDIO</span></div><form id="meal-form" class="meal-input-row"><label class="sr-only" for="meal-name">Describe your meal</label><input id="meal-name" maxlength="120" placeholder="Chicken alfredo pasta, or salmon with rice and broccoli…" value="${escapeHTML(state.sharedMeal?.name||'')}" required><button class="primary" id="illustrate-meal">Illustrate my meal</button></form><div class="meal-examples">Try ${['Chicken alfredo pasta','Strawberry pancakes with whipped cream','Salmon with rice and broccoli'].map(n=>`<button data-meal-example="${n}">${n}</button>`).join('')}<button type="button" id="manual-meal">Choose a simple illustration myself</button></div><p id="meal-ai-status" class="meal-ai-status" role="status">Composed on your device from an illustrated ingredient library. Unsupported details are labeled. No nutrition or insulin estimates.</p><div id="food-learning" aria-live="polite"></div><div id="meal-result"></div>${state.sharedMeal?`<div class="shared-meal"><div class="shared-meal-copy"><p>${escapeHTML(buddyName())}’s plate: <b>${escapeHTML(state.sharedMeal.name)}</b><small>${escapeHTML(state.sharedMeal.recipe?.note||'Previously saved illustration; re-illustrate to add meal components.')}</small></p></div><div class="shared-meal-actions"><button class="secondary" id="eat-again">Eating with ${escapeHTML(buddyName())}</button>${window.DiaLearning.storySeen()?'<button class="text-link" id="replay-meal-story">Why does mealtime insulin matter?</button>':''}</div></div>`:''}</section>`}
let mealJob=0;
function bindMealCard(){
 const form=$('#meal-form');if(!form)return;const input=$('#meal-name');
 input.addEventListener('input',()=>{mealJob++;$('#meal-result').innerHTML='';$('#meal-ai-status').textContent='Ready to illustrate your description.';$('#illustrate-meal').disabled=false;$('#illustrate-meal').textContent='Illustrate my meal';window.DiaLearning.updateFood(input.value)});
 if(input.value.trim())window.DiaLearning.updateFood(input.value);
 const replay=$('#replay-meal-story');if(replay)replay.onclick=()=>window.DiaLearning.showStory();
 form.onsubmit=async e=>{e.preventDefault();const name=input.value.trim();if(!name)return;
  const job=++mealJob,button=$('#illustrate-meal'),status=$('#meal-ai-status');button.disabled=true;button.textContent='Composing…';form.setAttribute('aria-busy','true');$('#meal-result').innerHTML='';
  try{const result=await window.DiaMeals.match(name,message=>{if(job===mealJob&&page==='home')status.textContent=message});if(job!==mealJob||page!=='home')return;status.textContent=result.meal.note;mealResult(name,result.meal);}
  catch{if(job!==mealJob||page!=='home')return;$('#meal-result').innerHTML='';status.textContent='Your illustration could not be drawn. Your description is still here; try again.';}
  finally{form.removeAttribute('aria-busy');if(job===mealJob&&page==='home'){button.disabled=false;button.textContent='Illustrate my meal';}}
 };
 document.querySelectorAll('[data-meal-example]').forEach(b=>b.onclick=()=>{input.value=b.dataset.mealExample;window.DiaLearning.updateFood(input.value);form.requestSubmit()});
 $('#manual-meal').onclick=()=>{const name=input.value.trim();if(!name){input.focus();toast('Name your meal first.');return;}mealJob++;$('#illustrate-meal').disabled=false;$('#illustrate-meal').textContent='Illustrate my meal';$('#meal-ai-status').textContent='Optional manual choice. Your original description stays unchanged.';$('#meal-result').innerHTML=`<label class="field-label" for="meal-illustration">Simple illustration<select id="meal-illustration">${window.DiaMeals.foods.map(f=>`<option value="${f.id}">${f.name}</option>`).join('')}</select></label><button class="secondary" id="use-simple-meal">Preview my choice</button>`;$('#use-simple-meal').onclick=()=>{const select=$('#meal-illustration'),label=window.DiaMeals.foods.find(f=>f.id===select.value).name;const recipe=window.DiaMeals.parse(select.value==='custom'?'':label);Object.assign(recipe,{name,coverage:'manual',note:'You chose a simple '+label.toLowerCase()+' illustration. It does not show every detail of your description.'});mealResult(name,recipe);};};
 if($('#eat-again'))$('#eat-again').onclick=()=>setActivity('Eating together');
}
function mealResult(name,recipe){
 $('#meal-result').innerHTML=`<div class="meal-result-inner"><canvas id="meal-preview" width="300" height="200" aria-label="${escapeHTML(name)}. ${escapeHTML(recipe.note)}"></canvas><div><div class="eyebrow">${recipe.coverage==='manual'?'YOUR MANUAL ILLUSTRATION':recipe.coverage==='composed'?'COMPONENT ILLUSTRATION':recipe.coverage==='partial'?'PARTIAL ILLUSTRATION':'GENERIC PLATE'}</div><h3>${escapeHTML(name)}</h3><p>${escapeHTML(recipe.note)}</p><div class="meal-components">${recipe.components.map(id=>`<span>${escapeHTML(window.DiaMeals.labels[id]||id)}</span>`).join('')}</div><button class="primary" id="share-meal">Share this meal with ${escapeHTML(buddyName())}</button></div></div>`;
 const c=$('#meal-preview').getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,300,200);c.save();c.translate(150,110);c.scale(3,3);window.DiaMealArt.render(c,recipe);c.restore();
 $('#share-meal').onclick=()=>{state.sharedMeal={name,food:recipe.base,recipe,matchedBy:recipe.coverage==='manual'?'manual':'local-components',createdAt:Date.now()};save();activity='Eating together';activityStarted=Date.now();home();window.DiaLearning.afterMeal();toast(buddyName()+' is joining you for '+name)};
}
